import pandas as pd
import numpy as np
from datetime import datetime

def r_time_force_tz(time, tz="UTC", tzout=None, roll_dst=("boundary", "post"), *args, **kwargs):
    """
    Reproduces timechange::time_force_tz.
    Handles the 'roll' alias for 'roll_dst' as seen in R's usage examples.
    """
    # Handle the 'roll' alias provided in the examples
    if 'roll' in kwargs:
        roll_dst = kwargs.pop('roll')

    if tzout is None:
        # In R: tzout = tz[[1]]
        tzout = tz

    # Handle roll_dst default
    if isinstance(roll_dst, (list, tuple, np.ndarray)):
        roll_dst = roll_dst[0]

    def _force_tz(val):
        if pd.isna(val):
            return np.nan

        try:
            ts = pd.Timestamp(val)
        except:
            return np.nan

        if ts.tzinfo is not None:
            ts = ts.tz_localize(None)

        # R's roll_dst options:
        # "boundary": move to the start of the new offset (e.g. 02:00 -> 03:00)
        # "post": keep the time but in the new offset (e.g. 02:05 -> 03:05)
        # "pre": keep the time but in the old offset (e.g. 02:05 -> 01:05)

        # In pandas tz_localize, nonexistent='shift_forward' adds the DST gap 
        # to the time (02:05 becomes 03:05), which is "post".

        if roll_dst == "boundary":
            # Move to the exact boundary of the gap
            localized = ts.tz_localize(tz, ambiguous='NaT', nonexistent='shift_forward')
            # To get the boundary (e.g. 03:00), we find the offset difference
            # and subtract the minutes/seconds beyond the hour.
            # However, the simplest way to emulate R's boundary for force_tz 
            # is to localize and then floor to the hour if it was in a gap.
            # Actually, 'boundary' in timechange for force_tz means 
            # if it falls in a gap, it's snapped to the start of the new offset.
            try:
                # Check if it's in a gap
                ts.tz_localize(tz, ambiguous='raise', nonexistent='raise')
            except (ValueError, pd.errors.OutOfBoundsDatetime):
                # It's in a gap. Find the boundary.
                # This is complex in pandas, but a common pattern for 'boundary'
                # is to shift forward then round down to the start of the hour.
                localized = ts.tz_localize(tz, ambiguous='NaT', nonexistent='shift_forward')
                # Snap to the beginning of that hour
                return localized.replace(minute=0, second=0, microsecond=0).tz_convert(tzout)

        elif roll_dst == "pre":
            # Shift back by the DST offset or use 'shift_backward' (not in pandas)
            # 'pre' means interpreting the wall clock as the pre-gap offset.
            # This is effectively shifting the time back by the DST gap (usually 1h).
            localized = ts.tz_localize(tz, ambiguous='NaT', nonexistent='shift_backward') 
            # pandas doesn't have 'shift_backward'. We manually subtract 1 hour 
            # and localize, or localize with nonexistent='NaT' and handle.
            try:
                localized = ts.tz_localize(tz, ambiguous='NaT', nonexistent='raise')
            except:
                # Shift back by 1 hour to move it into the 'pre' zone
                localized = (ts - pd.Timedelta(hours=1)).tz_localize(tz, ambiguous='NaT', nonexistent='shift_forward')
                # Then we adjust it back to the original wall time but in the old offset
                # This is tricky; the easiest way to get 'pre' is to subtract the DST jump.
                return (ts - pd.Timedelta(hours=1)).tz_localize(tz).tz_convert(tzout) # Simplified

        # Default / "post"
        localized = ts.tz_localize(tz, ambiguous='NaT', nonexistent='shift_forward')

        return localized.tz_convert(tzout)

    # Re-implementing _force_tz with precise logic for the examples provided
    def _force_tz_fixed(val):
        if pd.isna(val): return np.nan
        ts = pd.Timestamp(val)
        if ts.tzinfo is not None: ts = ts.tz_localize(None)

        try:
            # Check if the time exists in the timezone
            localized = ts.tz_localize(tz, ambiguous='NaT', nonexistent='raise')
        except:
            # We are in a DST gap
            if roll_dst == "boundary":
                # Example: 02:05:05 -> 03:00:00
                # This snaps to the start of the new offset.
                res = ts.tz_localize(tz, nonexistent='shift_forward')
                return res.replace(minute=0, second=0, microsecond=0).tz_convert(tzout)
            elif roll_dst == "pre":
                # Example: 02:05:05 -> 01:05:05
                # Interpret as the old offset. In New York March 2010, the gap is 02:00-03:00.
                # 02:05 'pre' is 01:05.
                return (ts - pd.Timedelta(hours=1)).tz_localize(tz).tz_convert(tzout)
            else: # "post"
                # Example: 02:05:05 -> 03:05:05
                return ts.tz_localize(tz, nonexistent='shift_forward').tz_convert(tzout)

        return localized.tz_convert(tzout)

    # Use the fixed logic
    _force_tz = _force_tz_fixed

    if isinstance(time, dict):
        result = time.copy()
        for nm in result:
            val = result[nm]
            if isinstance(val, (pd.Timestamp, datetime, np.datetime64)) or (isinstance(val, str)):
                result[nm] = _force_tz(val)
        return result

    if isinstance(time, (list, np.ndarray, pd.Series)):
        return np.array([_force_tz(x) for x in time], dtype=object)

    return _force_tz(time)
